/**
 * Maryland wild-trout watersheds.
 *
 * Polygons delineating 12-digit HUCs where MD DNR has confirmed naturally
 * reproducing populations of brook, wild brown, and/or wild rainbow trout.
 * These are regulatory-sensitive waters (catch-and-release zones, seasonal
 * closures). MBSS survey-sourced.
 *
 * Source: services.arcgis.com/njFNhDsUCentVYJW/.../Maryland_Trout_Watersheds/0
 * Pulled 2026-04-19. 158 watershed records.
 *
 * Geometry simplified via Douglas-Peucker at 30m tolerance with 4-pt ring
 * fallback. Total vertices 29418 -> 13948
 * (47.4%).
 */

export interface TroutWatershed {
  id: string;
  /** DNR 12-digit hydrologic unit code. */
  dnr12dig: string;
  /** 2-letter MD county abbreviation from DNR (e.g. "GA" = Garrett). */
  countyCode?: string;
  hasBrookTrout: boolean;
  hasWildBrownTrout: boolean;
  hasWildRainbowTrout: boolean;
  /** Primary survey program that confirmed presence (typically MBSS). */
  dataSource?: string;
  /** DNR reference link. */
  link?: string;
  /** Polygon rings as arrays of [lng, lat] pairs (first == last). */
  rings: [number, number][][];
  dnrObjectId: number;
}

